```ts
import * as ts from "typescript"

const program = ts.createProgram(["./index.ts"], { types: ["jasmine"] });
const sourceFile = program.getSourceFile("./index.ts");
const checker = program.getTypeChecker();

ts.forEachChild(sourceFile, checkNested);

function checkNested(node: ts.Node) {
  if (ts.isCallExpression(node)) {
    const signature = checker.getResolvedSignature(node);
    const file = signature.getDeclaration().getSourceFile();

    // file.fileName -> ​​​​​c:/git/testing-typescript/node_modules/@types/jasmine/index.d.ts​​​​​
    // file.moduleName -> ​​​​​undefined​​​​​
  }

  ts.forEachChild(node, checkNested);
}
```

